  "攻击力 +3；冰冻领域、冰冻瓶持续时间 +30%": "АТК +3; длительность Зоны заморозки и Ледяной бутылки +30%",
  "攻击力 +3；对 Boss（含触手）伤害 +20%": "АТК +3; урон по Боссам (и щупальцам) +20%",
  "攻击力 +3%": "АТК +3%",
  "攻击力 +35%，攻击速度 +25%，暴击率 +15%，暴击伤害 +50%": "АТК +35%, скорость атаки +25%, шанс крита +15%, крит. урон +50%",
