  "攻击力 +6%，暴击伤害 +20%": "АТК +6%, крит. урон +20%",
  "攻击力 +8%，普通攻击 15% 几率点燃目标": "АТК +8%, 15% шанс поджечь цель обычной атакой",
  "攻击速度": "Скорость атаки",
