  "攻击速度 +3%": "Скорость атаки +3%",
  "攻击速度 +35%，持续 9 秒。": "Скорость атаки +35% на 9 с.",
  "攻击速度 +50%，持续 8 秒。": "Скорость атаки +50% на 8 с.",
  "攻击速度 +6%；对飞行怪伤害 +15%": "Скорость атаки +6%; урон по летающим монстрам +15%",
  "攻击速度 +8%，城墙受到伤害 −8%；每波结束城墙多回复 2%": "Скорость атаки +8%, получаемый стеной урон −8%; после каждой волны стена лечится ещё на 2%",
  "攻击速度 +8%，射程 +3%": "Скорость атаки +8%, дальность +3%",
  "攻击速度 +8%；普通攻击 20% 几率点燃目标": "Скорость атаки +8%; 20% шанс поджечь цель обычной атакой",
  "攻速 +50%，8 秒": "СА +50%, 8 с",
