  "寄居蟹每挨 4 下就缩进壳里。别盯着一只打——连发弩、雷电法球能把火力分散到好几只身上！": "Рак-отшельник прячется в панцирь после каждых 4 ударов. Не фокусируйтесь на одном: Скорострельный арбалет и Шар молний распределяют огонь на нескольких!",
