  "溅射半径 +20，溅射伤害不再衰减（100%）": "Радиус разброса +20, урон по области больше не спадает (100%)",
  "箭穿过同一车道最多 5 只怪（每只 80% 伤害），无视 20% 护甲。": "Стрелы пробивают до 5 монстров на одной дорожке (по 80% урона), игнорируя 20% брони.",
  "箭袋": "Колчан",
  "箭命中后继续向后飞，再命中同一车道后方最多 2 只怪（40% 伤害）": "Стрелы после попадания летят дальше и поражают до 2 монстров позади на дорожке (40% урона)",
  "箭雨": "Дождь стрел",
  "交给我吧，国王爷爷！……哎呀，头盔又滑下来了。": "Предоставь это мне, дедушка-король! …Ой, шлем опять съехал.",
