  "解锁 3 倍速：战斗右下角的速度按钮": "Открывает скорость ×3: кнопка скорости справа внизу в бою",
  "解锁「王国小镇」（地图上的 🏘）和「每日挑战」（地图右下角）": "Открывает «Городок королевства» (🏘 на карте) и «Ежедневное испытание» (справа внизу на карте)",
