  "累计击败 10000 只怪物": "Суммарно победите 10000 монстров",
  "累计提前召唤 30 次": "Суммарно вызовите волну раньше срока 30 раз",
  "累计选择 50 张补给卡": "Суммарно выберите 50 карт припасов",
