  "升级城墙等级：城墙血量 +10%（{0}）": "Улучшить уровень стены: HP стены +10% ({0})",
  "升阶": "Повысить",
  "生命甲": "Броня жизни",
  "生命披风": "Плащ жизни",
  "圣光": "Священный свет",
  "圣光甲": "Броня священного света",
  "圣骑士甲": "Броня паладина",
  "圣泉披风": "Плащ святого источника",
  "胜利次数": "Побед",
  "胜率": "Процент побед",
  "失败": "Поражение",
  "失败安慰奖励": "Утешительный приз за поражение",
  "狮心王冠": "Корона львиного сердца",
  "狮牙坠": "Подвеска из львиного клыка",
  "石匠的儿子，背着一面大石盾。攻击力 ×0.97；城墙受到伤害 −12%，每波结束多修 3% 城墙。": "Сын каменщика с большим каменным щитом. АТК ×0.97; стена получает на 12% меньше урона и лечится ещё на 3% после каждой волны.",
  "石头拼成的小巨人，魔法伤害减免 75%。用物理武器打它！": "Маленький великан из камней, получает на 75% меньше магического урона. Бейте физическим оружием!",
