  "树桩怪": "Пень-монстр",
  "树桩怪不挨打就会回血。别分散火力，一只一只打掉。": "Пни-монстры лечатся, когда их не бьют. Не распыляйте огонь, убивайте по одному.",
  "双层箭袋": "Двойной колчан",
  "双刃回旋镖": "Двулезвийный бумеранг",
  "双羽箭袋": "Колчан двух перьев",
  "霜龙": "Морозный дракон",
  "霜龙空袭": "Налёт морозного дракона",
  "霜霜女王": "Королева Мороза",
  "霜霜女王冰封了城墙！": "Королева Мороза заморозила стену!",
  "霜霜女王的回声": "Эхо Королевы Мороза",
  "霜霜女王会冰封城墙，期间无法修复。在冰封之前把城墙修好！": "Королева Мороза замораживает стену, и пока она заморожена, починить её нельзя. Почините стену до заморозки!",
  "霜霜女王其实很温柔，只是不太会说话。最后的目的地：熔岩裂隙。": "Королева Мороза на самом деле очень нежная, просто не умеет говорить. Последний пункт: Лавовый разлом.",
  "霜霜女王召唤的小冰龙。": "Ледяной дракончик, призванный Королевой Мороза.",
  "霜羽箭袋": "Колчан морозного пера",
  "顺风旗": "Флаг попутного ветра",
  "死后的尖刺扎得更疼。": "После смерти шипы колются больнее.",
  "死后留下更大、更久的火焰地带。": "После смерти оставляет огненное пятно побольше и подольше.",
  "死后留下一片火焰，经过的怪物会加速。": "После смерти оставляет огонь, и проходящие через него монстры ускоряются.",
  "死亡时裂成 3 只跑得很快的小南瓜。": "При смерти раскалывается на 3 очень быстрые маленькие тыквы.",
  "死亡时喷出孢子云，让附近的怪加速。尽量在远处打掉它。": "При смерти выпускает облако спор, ускоряющее монстров рядом. По возможности убивайте издалека.",
  "四叶草": "Четырёхлистный клевер",
  "四叶银章": "Серебряная медаль с четырёхлистником",
  "四只一组冲过来的铁甲狼。": "Железные волки, нападающие по четыре.",
  "速攻": "Натиск",
  "速攻关：骷髅战车撞墙伤害很高，冰冻领域和冰冻瓶是救命稻草。": "Уровень «Натиск»: скелетные колесницы сильно бьют по стене, спасение — Зона заморозки и Ледяная бутылка.",
  "速攻关：每 13 秒来一波！企鹅和狼群都很快，冰冻领域和箭雨要及时放。": "Уровень «Натиск»: волна каждые 13 секунд! Пингвины и волчьи стаи быстры, так что применяйте Зону заморозки и Дождь стрел вовремя.",
  "速攻关：每 14 秒就来一波，不等你清场！冰冻领域能拖住兔子潮。": "Уровень «Натиск»: волна каждые 14 секунд, не ждём очистки поля! Зона заморозки задержит заячий прилив.",
  "速攻关！大群云朵羊一波接一波，剃光毛的羊跑得飞快。冰冻领域和箭雨很有用。": "Уровень «Натиск»! Большие стада облачных овец идут волна за волной, а остриженные овцы бегут быстро. Очень пригодятся Зона заморозки и Дождь стрел.",
  "随身带的小物件。": "Мелочь, которую носишь с собой.",
  "碎冰": "Ледяной осколок",
  "缩壳": "В панцирь",
  "缩壳的时间更长。": "Дольше сидит в панцире.",
  "所以裂缝，是你的\"不想一个人\"？": "Значит, трещина — это твоё «не хочу быть один»?",
  "所有怪物速度 −3%": "Скорость всех монстров −3%",
  "锁子甲": "Кольчуга",
  "它和骨头先生一样会召唤骷髅、被打倒后复活一次，只是更硬。": "Как и мистер Кость, призывает скелетов и воскресает один раз после поражения, только прочнее.",
  "它在说谢谢诶。": "Он говорит спасибо!",
