  "铁环冠": "Корона железного кольца",
  "铁甲对魔法怕不怕呀？我来试试！": "А железная броня боится магии? Сейчас проверю!",
  "铁盔上两只弯角，橘色的胡子编成了辫子。": "На железном шлеме два изогнутых рога, а рыжая борода заплетена в косы.",
  "铁狼": "Железный волк",
  "铁狼四只一组冲来。炉渣团死后的火焰会让经过的怪物加速。": "Железные волки нападают по четыре. Огонь от умирающих шлаковых комьев ускоряет проходящих монстров.",
  "铁狼突袭": "Налёт железных волков",
  "铁皮盔": "Шлем из жести",
  "铁片甲": "Броня из железных пластин",
  "铁雪人": "Железный снеговик",
  "铁雪人死后会裂成三个小雪团；炉火小鬼的火球比原来疼得多。": "Железные снеговики после смерти раскалываются на три маленьких снежка; огненные шары огненных чертят бьют намного больнее прежнего.",
  "铁战车": "Железная колесница",
  "铁战车撞墙很疼，冲得又快——冰冻领域是救命的。": "Железные колесницы больно бьют по стене и быстро мчатся — спасает Зона заморозки.",
  "停在远处给怪物套泡泡，泡泡能挡住一次攻击。连发弩、雷电法球能很快戳破泡泡。": "Держится вдали и накладывает на монстров пузыри; пузырь блокирует одну атаку. Скорострельные арбалеты и шары молний быстро лопают пузыри.",
  "通关第 {0} 关后，这里会搬来一位新邻居": "После прохождения уровня {0} здесь поселится новый сосед",
  "通关第 {0} 关后解锁消耗品栏位。现在可以先买好。": "Ячейки расходников открываются после прохождения уровня {0}. Пока можно закупиться.",
  "通关第 {0} 关后开放": "Откроется после прохождения уровня {0}",
  "通关第 {0} 关后开放「装备」：头盔、披风、盔甲、箭袋、饰品和鞋子": "После прохождения уровня {0} откроется «Снаряжение»: шлемы, плащи, броня, колчаны, аксессуары и сапоги",
