  "游戏设计 · 程序 · 美术 · 音效": "Дизайн игры · Программирование · Графика · Звук",
  "游侠靴": "Сапоги следопыта",
  "有家的感觉，原来是这样暖暖的。": "Вот каково это, когда есть дом: тепло и уютно.",
  "有求必应": "Исполнитель желаний",
  "有人住？那更要登记了！啪嗒——（合上了壳）": "Тут кто-то живёт? Тем более надо записать! Щёлк — (захлопнул раковину)",
  "又厚又硬，2 秒没挨打就会慢慢回血。集中火力一口气打掉。": "Толстый и прочный, медленно лечится, если 2 секунды его не бьют. Сосредоточьте огонь и убейте разом.",
  "余烬斗篷": "Плащ из углей",
